import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Gallery","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/gallery.md","filePath":"03-developer/models/gallery.md"}`),a={name:`03-developer/models/gallery.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="gallery" tabindex="-1">Gallery <a class="header-anchor" href="#gallery" aria-label="Permalink to “Gallery”">​</a></h1><p>Manages image galleries, including their title, description, publication status, view counter, and associated images. Each gallery can contain multiple images, and its featured image is managed separately through the Media Library.</p><h2 id="galleries-table" tabindex="-1"><code>galleries</code> table <a class="header-anchor" href="#galleries-table" aria-label="Permalink to “galleries table”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique gallery ID</td></tr><tr><td><code>title</code></td><td>TEXT</td><td>No</td><td>Gallery title</td></tr><tr><td><code>slug</code></td><td>VARCHAR(255)</td><td>No</td><td>Unique text identifier used in the gallery URL</td></tr><tr><td><code>description</code></td><td>LONGTEXT</td><td>Yes</td><td>Gallery description</td></tr><tr><td><code>view</code></td><td>TINYINT UNSIGNED</td><td>No</td><td>Gallery view counter; defaults to <code>0</code></td></tr><tr><td><code>status</code></td><td>TINYINT UNSIGNED</td><td>No</td><td>Gallery status; defaults to <code>0</code>, with the application using the status values <code>0</code> and <code>1</code></td></tr><tr><td><code>user_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the user who created the gallery; associated with the <code>users</code> table</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation date</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Date of last update</td></tr></tbody></table><h2 id="properties-and-methods" tabindex="-1">Properties and methods <a class="header-anchor" href="#properties-and-methods" aria-label="Permalink to “Properties and methods”">​</a></h2><h3 id="translatable" tabindex="-1"><code>$translatable</code> <a class="header-anchor" href="#translatable" aria-label="Permalink to “$translatable”">​</a></h3><p>The <code>title</code> and <code>description</code> fields support storing and retrieving translations.</p><h3 id="images" tabindex="-1"><code>images()</code> <a class="header-anchor" href="#images" aria-label="Permalink to “images()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <code>Image</code> model and retrieves the images belonging to the gallery based on <code>gallery_id</code>.</p><p>Images are ordered first by <code>sort</code> in ascending order, then by <code>id</code> in descending order.</p><h3 id="registermediaconversions-media-media-null-void" tabindex="-1"><code>registerMediaConversions(Media $media = null): void</code> <a class="header-anchor" href="#registermediaconversions-media-media-null-void" aria-label="Permalink to “registerMediaConversions(Media $media = null): void”">​</a></h3><p>Defines the gallery&#39;s media conversions and optimizations:</p><ul><li><code>gallery-image</code>: Converts and optimizes the image.</li><li><code>gthumb</code>: Creates a thumbnail with dimensions configured through <code>gallery_thumb</code>; the image is cropped and optimized, and its format is taken from the <code>optimize</code> settings.</li><li>If the <code>watermark</code> setting is enabled, a logo watermark is applied to the thumbnail, with configurable position, size, and opacity.</li></ul><p>The <code>gthumb</code> conversion is defined with <code>nonQueued()</code> so it is processed without being added to the media processing queue.</p><h3 id="getroutekeyname" tabindex="-1"><code>getRouteKeyName()</code> <a class="header-anchor" href="#getroutekeyname" aria-label="Permalink to “getRouteKeyName()”">​</a></h3><p>Sets <code>slug</code> as the model&#39;s route key. As a result, Route Model Binding uses <code>slug</code> instead of <code>id</code>.</p><h3 id="imgurl" tabindex="-1"><code>imgUrl()</code> <a class="header-anchor" href="#imgurl" aria-label="Permalink to “imgUrl()”">​</a></h3><p>Returns the gallery&#39;s featured image URL. If the model has an image in the Media Library, the URL of the <code>gthumb</code> conversion for the first image is returned; otherwise, the URL of the site&#39;s default logo is returned.</p><p>This method returns the featured image, not the list of associated images retrieved through <code>images()</code>.</p><h3 id="author" tabindex="-1"><code>author()</code> <a class="header-anchor" href="#author" aria-label="Permalink to “author()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./user.html">User</a> model and returns the user associated with the gallery.</p><h3 id="attachs" tabindex="-1"><code>attachs()</code> <a class="header-anchor" href="#attachs" aria-label="Permalink to “attachs()”">​</a></h3><p>Defines a polymorphic <code>morphMany</code> relationship with the <a href="./attachment.html">Attachment</a> model and retrieves the attachments associated with the gallery.</p><h3 id="weburl" tabindex="-1"><code>webUrl()</code> <a class="header-anchor" href="#weburl" aria-label="Permalink to “webUrl()”">​</a></h3><p>Generates the gallery page URL using the route named <code>client.gallery</code> and the <code>slug</code> value, then adjusts the URL language with <code>fixUrlLang()</code>.</p><h3 id="comments" tabindex="-1"><code>comments()</code> <a class="header-anchor" href="#comments" aria-label="Permalink to “comments()”">​</a></h3><p>Defines a polymorphic <code>morphMany</code> relationship with the <a href="./comment.html">Comment</a> model and retrieves the comments associated with the gallery, without applying any specific comment status filter in this method.</p><h3 id="approvedcomments" tabindex="-1"><code>approvedComments()</code> <a class="header-anchor" href="#approvedcomments" aria-label="Permalink to “approvedComments()”">​</a></h3><p>Retrieves the comments associated with the gallery using the same polymorphic relationship, but returns only comments with <code>status = 1</code>.</p><h3 id="markup" tabindex="-1"><code>markup()</code> <a class="header-anchor" href="#markup" aria-label="Permalink to “markup()”">​</a></h3><p>Displays the appropriate Schema Markup output for the gallery.</p>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};